int getFirstSetBit(int n) {

    // If no set bit
    if (n == 0) return 0;

    int pos = 1;

    // Left shift a mask and check each bit
    while ((n & (1 << (pos - 1))) == 0) {
        pos++;
    }

    return pos;
}

