    #include <bits/stdc++.h>
using namespace std;

int getFirstSetBit(int n) {

    // If no set bit 
    if (n == 0) return 0;

    int res = 1;

    // Right shift and check LSB
    while (!(n & 1)) {
        n = n >> 1;
        res++;
    }

    return res;
}

int main() {
    int n = 18;
    cout << getFirstSetBit(n);
    return 0;
}


